from collections import deque

def transform(grid):
    h,w=len(grid),len(grid[0]); seen=set(); q=deque()
    for r in range(h):
        for c in (0,w-1):
            if grid[r][c] != 6 and (r,c) not in seen: seen.add((r,c)); q.append((r,c))
    for c in range(w):
        for r in (0,h-1):
            if grid[r][c] != 6 and (r,c) not in seen: seen.add((r,c)); q.append((r,c))
    while q:
        r,c=q.popleft()
        for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0<=nr<h and 0<=nc<w and grid[nr][nc]!=6 and (nr,nc) not in seen:
                seen.add((nr,nc)); q.append((nr,nc))
    holes={(r,c) for r in range(h) for c in range(w) if grid[r][c]!=6 and (r,c) not in seen}
    # Keep only the smallest bounded empty component.
    comps=[]
    while holes:
        start=holes.pop(); comp={start}; q=deque([start])
        while q:
            r,c=q.popleft()
            for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if (nr,nc) in holes: holes.remove((nr,nc)); comp.add((nr,nc)); q.append((nr,nc))
        comps.append(comp)
    out=[row[:] for row in grid]
    if comps:
        for comp in comps:
            for r,c in comp: out[r][c]=4
    return out

